public void put(int key, int value) {
    Node n = map.get(key);
    if (n != null) { n.val = value; remove(n); addFront(n); return; }
    if (map.size() == cap) {
        Node lru = tail.prev;
        remove(lru);              // map.remove(lru.key) is missing
    }
    n = new Node(key, value);
    map.put(key, n);
    addFront(n);
}
